CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, username text NOT NULL, username_key text NOT NULL UNIQUE, password_hash text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS actors (id uuid PRIMARY KEY, user_id uuid UNIQUE REFERENCES users(id), username text NOT NULL, kind text NOT NULL CHECK(kind IN ('account','guest','bot')), created_at timestamptz NOT NULL DEFAULT now(), CHECK ((kind='account')=(user_id IS NOT NULL)));
CREATE TABLE IF NOT EXISTS auth_identities (provider text NOT NULL, subject text NOT NULL, user_id uuid NOT NULL REFERENCES users(id), PRIMARY KEY(provider,subject));
CREATE TABLE IF NOT EXISTS sessions (id uuid PRIMARY KEY, actor_id uuid NOT NULL REFERENCES actors(id), token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS realtime_tickets (token_hash text PRIMARY KEY, session_id uuid NOT NULL REFERENCES sessions(id), expires_at timestamptz NOT NULL, consumed_at timestamptz);
CREATE TABLE IF NOT EXISTS oauth_states (state_hash text PRIMARY KEY, provider text NOT NULL, verifier text NOT NULL, binding_hash text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS rooms (id uuid PRIMARY KEY, creator_user_id uuid NOT NULL REFERENCES users(id), host_actor_id uuid REFERENCES actors(id), code text UNIQUE, visibility text NOT NULL CHECK(visibility IN ('public','code','private')), phase text NOT NULL, version integer NOT NULL DEFAULT 1 CHECK(version>0), state jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, CHECK ((visibility='private')=(code IS NULL)));
CREATE INDEX IF NOT EXISTS rooms_phase ON rooms(phase);
CREATE TABLE IF NOT EXISTS room_members (room_id uuid NOT NULL REFERENCES rooms(id), actor_id uuid NOT NULL REFERENCES actors(id), role text NOT NULL CHECK(role IN ('participant','spectator')), status text NOT NULL CHECK(status IN ('active','left','kicked')), joined_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(room_id,actor_id));
ALTER TABLE rooms ADD CONSTRAINT host_belongs_to_room FOREIGN KEY(id,host_actor_id) REFERENCES room_members(room_id,actor_id) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE IF NOT EXISTS invitations (token_hash text PRIMARY KEY, room_id uuid NOT NULL REFERENCES rooms(id), expires_at timestamptz NOT NULL, consumed_at timestamptz, consumed_by uuid REFERENCES actors(id), revoked_at timestamptz, CHECK ((consumed_at IS NULL)=(consumed_by IS NULL)));
CREATE TABLE IF NOT EXISTS races (id uuid PRIMARY KEY, room_id uuid NOT NULL REFERENCES rooms(id), phase text NOT NULL CHECK(phase IN ('countdown','racing','results','interrupted')), text text NOT NULL, settings jsonb NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz, finished_at timestamptz);
CREATE TABLE IF NOT EXISTS results (id uuid PRIMARY KEY, race_id uuid NOT NULL REFERENCES races(id), room_id uuid NOT NULL REFERENCES rooms(id), actor_id uuid NOT NULL REFERENCES actors(id), data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(race_id,actor_id));
CREATE INDEX IF NOT EXISTS results_actor ON results(actor_id);
CREATE TABLE IF NOT EXISTS room_events (room_id uuid NOT NULL REFERENCES rooms(id), version integer NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(room_id,version));
CREATE TABLE IF NOT EXISTS command_receipts (actor_id uuid NOT NULL REFERENCES actors(id), command_id uuid NOT NULL, room_id uuid REFERENCES rooms(id), response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(actor_id,command_id));
CREATE TABLE IF NOT EXISTS rate_limits (key text PRIMARY KEY, window_start timestamptz NOT NULL, count integer NOT NULL);
